  /* ---------- perbendaharaan kata untuk pemeriksa ejaan ---------- */
  var KATA_DIKENAL = null;
  function bangunKamus() {
    if (KATA_DIKENAL) return KATA_DIKENAL;
    KATA_DIKENAL = {};
    var tambah = function (teks) {
      String(teks).toLowerCase().replace(/<[^>]*>/g, " ")
        .replace(/[^a-z\u00e0-\u00ff\s-]/g, " ").split(/\s+/)
        .forEach(function (k) { if (k.length > 1) KATA_DIKENAL[k] = true; });
    };
    var telusur = function (nilai) {
      if (nilai == null) return;
      if (typeof nilai === "string") { tambah(nilai); return; }
      if (Array.isArray(nilai)) { nilai.forEach(telusur); return; }
      if (typeof nilai === "object") { Object.keys(nilai).forEach(function (k) { telusur(nilai[k]); }); }
    };
    telusur(AWAL); telusur(UNIT); telusur(AKHIR);
    /* kata tugas dan kata umum yang mungkin belum muncul pada teks modul */
    ("saya aku kamu anda dia kami kita mereka ini itu yang dan atau tetapi karena sebab jika kalau " +
      "akan sudah belum sedang masih hanya juga lagi sangat sekali tidak bukan ada tanpa dengan untuk " +
      "dari ke di pada oleh sebagai agar supaya ketika setelah sebelum selama hingga sampai bila " +
      "setiap semua banyak sedikit besar kecil baik buruk senang suka ingin mau bisa dapat harus " +
      "pergi datang pulang makan minum tidur bangun mandi belajar bekerja membaca menulis berbicara " +
      "mendengar melihat tinggal nama umur tahun bulan hari pagi siang sore malam rumah sekolah kota " +
      "negara bahasa indonesia teman keluarga ayah ibu kakak adik anak orang sekarang kemarin besok " +
      "terima kasih maaf permisi selamat halo hai ya iya tolong silakan sama sudahkah apakah bagaimana " +
      "mengapa kapan siapa berapa dimana kemana").split(/\s+/).forEach(function (k) { KATA_DIKENAL[k] = true; });
    return KATA_DIKENAL;
  }

  function periksaTulisan(teks, targetKata) {
    var bersih = String(teks).trim();
    var kata = bersih ? bersih.split(/\s+/) : [];
    var kalimat = bersih.split(/[.!?]+/).map(function (x) { return x.trim(); })
      .filter(function (x) { return x.length > 0; });
    var kamus = bangunKamus();
    var asing = [];
    kata.forEach(function (k) {
      var bare = k.toLowerCase().replace(/[^a-z\u00e0-\u00ff-]/g, "");
      if (bare.length > 2 && !kamus[bare] && asing.indexOf(bare) < 0) asing.push(bare);
    });
    var nPanjang = Math.min(1, targetKata ? kata.length / targetKata : (kata.length >= 15 ? 1 : kata.length / 15));
    var berkapital = kalimat.length ? kalimat.filter(function (x) {
      return /^[A-Z\u00c0-\u00dd]/.test(x);
    }).length / kalimat.length : 0;
    var berakhir = /[.!?]\s*$/.test(bersih) ? 1 : 0;
    var ejaan = kata.length ? Math.max(0, 1 - asing.length / kata.length * 1.6) : 0;
    var nilai = ejaan * 0.4 + nPanjang * 0.3 + berkapital * 0.15 + berakhir * 0.15;
    return {
      nilai: Math.max(0, Math.min(1, nilai)),
      kata: kata.length, kalimat: kalimat.length, asing: asing,
      panjangCukup: nPanjang >= 0.85, kapital: berkapital >= 0.9, akhiran: berakhir === 1,
      targetKata: targetKata
    };
  }

  /* ---------- kotak menulis ---------- */
  function buatTulis(b, hal, kunciDasar, judulHal) {
    var kunci = kunciDasar + "." + (b.label || "tulis");
    daftarPoin(hal, kunci);
    daftarNilai(hal, kunci);
    var kotak = E("div");
    if (b.perintah) kotak.appendChild(E("div", "perintah", b.perintah));
    var ta = document.createElement("textarea");
    ta.value = JAWAB[kunci] || "";
    if (b.tinggi) ta.style.minHeight = b.tinggi + "px";
    ta.addEventListener("input", function () {
      JAWAB[kunci] = ta.value; simpan();
      if (ta.value.trim().length > 5) tandaiPoin(hal, kunci);
    });
    kotak.appendChild(ta);
    var deret = E("div", "deret");
    var hitung = E("span", "skor", "");
    function perbaruiHitung() {
      var kata = ta.value.trim() ? ta.value.trim().split(/\s+/).length : 0;
      hitung.textContent = kata + " kata";
    }
    /* sasaran panjang dihitung lebih dahulu agar penilaian otomatis dapat memakainya */
    var angkaKataAwal = { satu: 1, dua: 2, tiga: 3, empat: 4, lima: 5, enam: 6, tujuh: 7, delapan: 8, sembilan: 9, sepuluh: 10 };
    var targetKata = 0;
    var teksPerintahAwal = String(b.perintah || "").toLowerCase();
    var ck = teksPerintahAwal.match(/(\d+)\s*kata/);
    if (ck) targetKata = parseInt(ck[1], 10);
    if (!targetKata) {
      var cl = teksPerintahAwal.match(/(\d+|satu|dua|tiga|empat|lima|enam|tujuh|delapan|sembilan|sepuluh)[^.]{0,18}kalimat/);
      if (cl) {
        var jm = parseInt(cl[1], 10) || angkaKataAwal[cl[1]] || 4;
        targetKata = jm * 6;
      }
    }
    if (!targetKata) targetKata = 18;

    var tungguPeriksa = null;
    ta.addEventListener("input", function () {
      perbaruiHitung();
      if (tungguPeriksa) clearTimeout(tungguPeriksa);
      tungguPeriksa = setTimeout(function () {
        if (ta.value.trim().length < 3) return;
        try {
          var h = periksaTulisan(ta.value, targetKata);
          setNilai(hal, kunci, h.nilai);
        } catch (e) { }
      }, 900);
    });
    perbaruiHitung();

    var tbPeriksa = E("button", "tbl", "Periksa tulisan"); tbPeriksa.type = "button";
    deret.appendChild(tbPeriksa);
    deret.appendChild(hitung);
    kotak.appendChild(deret);

    var papan = E("div", "periksa-tulis");
    kotak.appendChild(papan);
    tbPeriksa.addEventListener("click", function () {
      if (ta.value.trim().length < 3) {
        papan.className = "periksa-tulis tampil";
        papan.innerHTML = "<p>Tulis dahulu jawaban Anda pada kotak di atas.</p>";
        return;
      }
      var h = periksaTulisan(ta.value, targetKata);
      var persen = Math.round(h.nilai * 100);
      var cap = persen >= 80 ? "Sudah baik" : (persen >= 60 ? "Perlu diperbaiki" : "Belum sesuai");
      var kelas = persen >= 80 ? "" : (persen >= 60 ? " sedang" : " kurang");
      var baris = [
        '<li class="' + (h.panjangCukup ? "ya" : "tidak") + '">Panjang tulisan: ' + h.kata +
        " kata dalam " + h.kalimat + " kalimat" +
        (h.panjangCukup ? "." : ", sasarannya sekitar " + h.targetKata + " kata.") + "</li>",
        '<li class="' + (h.kapital ? "ya" : "tidak") + '">Huruf kapital pada awal kalimat' +
        (h.kapital ? " sudah tepat." : " masih ada yang terlewat.") + "</li>",
        '<li class="' + (h.akhiran ? "ya" : "tidak") + '">Tanda baca penutup' +
        (h.akhiran ? " sudah ada." : " belum ada pada kalimat terakhir.") + "</li>",
        '<li class="' + (h.asing.length ? "tidak" : "ya") + '">Ejaan: ' +
        (h.asing.length ? h.asing.length + " kata perlu diperiksa." : "seluruh kata dikenali.") + "</li>"
      ];
      papan.className = "periksa-tulis tampil";
      papan.innerHTML =
        '<div class="nilai-tulis"><b>Hasil pemeriksaan</b>' +
        '<span class="cap-tulis' + kelas + '">' + cap + " \u00b7 " + persen + "</span></div>" +
        "<ul>" + baris.join("") + "</ul>" +
        (h.asing.length ? '<p class="ejaan"><b>Perlu diperiksa:</b> ' +
          h.asing.slice(0, 8).join(", ") + "</p>" : "") +
        '<p class="ejaan"><b>Catatan.</b> Pemeriksaan ini menilai panjang, ejaan, huruf kapital, ' +
        "dan tanda baca. Ketepatan isi tetap dinilai pengajar.</p>";
      JAWAB[kunci] = ta.value; simpan();
      tandaiPoin(hal, kunci);
      setNilai(hal, kunci, h.nilai);
    });
    REGISTER.push({ label: judulHal + " — " + (b.perintah || b.label || "Catatan"), ambil: function () { return ta.value; } });
    return kotak;
  }

  /* ---------- daftar centang ---------- */
  function buatCek(b, hal, kunciDasar) {
    var kotak = E("div", "kotak");
    b.butir.forEach(function (t, i) {
      var kunci = kunciDasar + ".ck" + i;
      daftarPoin(hal, kunci);
      var baris = document.createElement("label");
      baris.style.display = "flex"; baris.style.gap = "10px"; baris.style.alignItems = "flex-start";
      baris.style.marginBottom = "8px"; baris.style.cursor = "pointer";
      var c = document.createElement("input"); c.type = "checkbox";
      c.checked = JAWAB[kunci] === "ya";
      c.style.marginTop = "5px";
      c.addEventListener("change", function () {
        JAWAB[kunci] = c.checked ? "ya" : ""; simpan();
        if (c.checked) tandaiPoin(hal, kunci); else { delete POIN[hal].selesai[kunci]; perbaruiLaju(); }
      });
      baris.appendChild(c); baris.appendChild(E("span", "cek-teks", t));
      kotak.appendChild(baris);
    });
    return kotak;
  }


  /* ---------- latihan: menyusun kalimat ---------- */
  function buatSusun(b, hal, kunciDasar) {
    var kotak = E("div", "susun");
    var semua = [];
    b.butir.forEach(function (s, i) {
      var kunci = kunciDasar + ".ss" + i;
      daftarPoin(hal, kunci); daftarNilai(hal, kunci);
      var butir = E("div", "butir");
      butir.appendChild(E("div", "nomor-butir", "KALIMAT " + (i + 1) + (s.petunjuk ? " · " + s.petunjuk : "")));
      var jawab = E("div", "jawab");
      var kosong = E("span", "kosong", "Klik kata di bawah untuk menyusun kalimat.");
      jawab.appendChild(kosong);
      var bank = E("div", "bank");
      function segarkan() {
        kosong.style.display = jawab.querySelectorAll(".keping").length ? "none" : "block";
      }
      acak(s.kata).forEach(function (k) {
        var t = E("div", "keping", '<span class="keping-teks">' + k + '</span>');
        t.setAttribute("role", "button");
        t.setAttribute("tabindex", "0");
        t.addEventListener("click", function () {
          if (modeSunting) return;
          if (t.parentNode === bank) jawab.appendChild(t); else bank.appendChild(t);
          jawab.classList.remove("benar", "salah");
          segarkan();
        });
        bank.appendChild(t);
      });
      butir.appendChild(jawab); butir.appendChild(bank);
      kotak.appendChild(butir);
      semua.push({ jawab: jawab, benar: s.benar, kunci: kunci, bank: bank, segarkan: segarkan });
      segarkan();
    });
    var deret = E("div", "deret");
    var periksa = E("button", "tbl", "Periksa kalimat"); periksa.type = "button";
    var lihat = E("button", "tbl garis", "Tampilkan kunci"); lihat.type = "button";
    daftarTombolKunci(hal, lihat);
    var skor = E("span", "skor", "");
    periksa.addEventListener("click", function () {
      var benar = 0;
      semua.forEach(function (x) {
        var susunan = Array.prototype.map.call(x.jawab.querySelectorAll(".keping"), function (k) { return k.textContent; }).join(" ");
        var ok = normal(susunan) === normal(x.benar);
        x.jawab.classList.remove("benar", "salah");
        x.jawab.classList.add(ok ? "benar" : "salah");
        if (ok) benar++;
        JAWAB[x.kunci] = susunan;
        if (susunan.trim() !== "") tandaiPoin(hal, x.kunci);
        if (SKOR[x.kunci] === undefined || ok) SKOR[x.kunci] = ok ? 1 : 0;
      });
      skor.textContent = benar + " dari " + semua.length + " kalimat benar";
      simpanNilai(); simpan(); perbaruiLaju(); simpanRekap();
    });
    lihat.addEventListener("click", function () {
      semua.forEach(function (x) {
        Array.prototype.forEach.call(x.jawab.querySelectorAll(".keping"), function (k) { x.bank.appendChild(k); });
        x.benar.split(" ").forEach(function (kata) {
          var daftar = x.bank.querySelectorAll(".keping");
          for (var i = 0; i < daftar.length; i++) {
            if (normal(daftar[i].textContent) === normal(kata)) { x.jawab.appendChild(daftar[i]); break; }
          }
        });
        x.jawab.classList.remove("salah"); x.jawab.classList.add("benar");
        x.segarkan();
        JAWAB[x.kunci] = x.benar; tandaiPoin(hal, x.kunci);
        if (SKOR[x.kunci] === undefined) SKOR[x.kunci] = 0;
      });
      simpanNilai(); simpanRekap();
      skor.textContent = "kunci ditampilkan \u00b7 butir yang belum dijawab dinilai nol";
      simpan(); perbaruiLaju();
    });
    deret.appendChild(periksa); deret.appendChild(lihat); deret.appendChild(skor);
    kotak.appendChild(deret);
    return kotak;
  }

  /* ---------- perender blok ---------- */
  function render(b, induk, hal, kunciDasar, judulHal, nomorKegiatan) {
    switch (b.j) {
      case "p": induk.appendChild(E("p", null, b.t)); break;
      case "ul": var u = E("ul"); b.b.forEach(function (x) { u.appendChild(E("li", null, x)); }); induk.appendChild(u); break;
      case "ol": var o = E("ol"); b.b.forEach(function (x) { o.appendChild(E("li", null, x)); }); induk.appendChild(o); break;
      case "kotak":
        var k = E("div", "kotak" + (b.kelas ? " " + b.kelas : ""));
        if (b.judul) k.appendChild(E("h4", null, b.judul));
        (b.b || []).forEach(function (x) { k.appendChild(E("p", null, x)); });
        induk.appendChild(k); break;
      case "baca":
        var t = E("div", "teks-baca");
        if (b.judul) t.appendChild(E("div", "judul-teks", b.judul));
        if (b.sumber) t.appendChild(E("div", "sumber", "Sumber: " + b.sumber));
        (b.b || []).forEach(function (x) { t.appendChild(E("p", null, x)); });
        induk.appendChild(t); break;
      case "tabel":
        var tb = E("table"), thead = E("thead"), tr = E("tr");
        (b.kepala || []).forEach(function (h) { tr.appendChild(E("th", null, h)); });
        thead.appendChild(tr); tb.appendChild(thead);
        var tbody = E("tbody");
        (b.baris || []).forEach(function (r) {
          var baris = E("tr");
          r.forEach(function (sel) { baris.appendChild(E("td", null, sel)); });
          tbody.appendChild(baris);
        });
        tb.appendChild(tbody); induk.appendChild(tb); break;
      case "transkrip":
        var tk = E("div", "transkrip");
        b.b.forEach(function (r) {
          var baris = E("div", "baris");
          baris.appendChild(E("div", "pelaku", r[0]));
          baris.appendChild(E("div", "ucap", r[1]));
          baris.appendChild(E("div", "penanda", r[2] || ""));
          tk.appendChild(baris);
        });
        induk.appendChild(tk); break;
      case "audio": case "video": induk.appendChild(buatMedia(b, hal)); break;
      case "mars": induk.appendChild(buatMars(b)); break;
      case "sertifikat": induk.appendChild(buatSertifikat()); break;
      case "kelas": induk.appendChild(buatKelas()); break;
      case "pantau": induk.appendChild(buatPantau()); break;
      case "lafal": induk.appendChild(buatLafal(b, hal, kunciDasar + ".lafal")); break;
      case "fotodialog": induk.appendChild(buatFotoDialog(b, hal, kunciDasar)); break;
      case "fotoslot": induk.appendChild(buatFotoSlot(b, hal)); break;
      case "kegiatan":
        nomorKegiatan.n++;
        var kop = E("div", "kegiatan-kop");
        kop.appendChild(E("span", "nomor", "KEGIATAN " + nomorKegiatan.n));
        kop.appendChild(E("span", "judul", b.judul || ""));
        induk.appendChild(kop);
        if (b.perintah) induk.appendChild(E("div", "perintah", b.perintah));
        break;
      case "pg": induk.appendChild(buatPG(b, hal, kunciDasar)); break;
      case "cloze": induk.appendChild(buatCloze(b, hal, kunciDasar)); break;
      case "jodoh": induk.appendChild(buatJodoh(b, hal, kunciDasar)); break;
      case "susun": induk.appendChild(buatSusun(b, hal, kunciDasar)); break;
      case "kartu": induk.appendChild(buatKartu(b)); break;
      case "tulis": induk.appendChild(buatTulis(b, hal, kunciDasar, judulHal)); break;
      case "cek": induk.appendChild(buatCek(b, hal, kunciDasar)); break;
    }
  }

  /* ---------- menyusun halaman ---------- */
  var isi = document.getElementById("isi");
  var navAwal = document.getElementById("daftar-awal");
  var navUnit = document.getElementById("daftar-unit");
  var navAkhir = document.getElementById("daftar-akhir");

  function tautan(wadah, hal, nomor, judul) {
    var a = E("a", null, '<span class="n">' + nomor + '</span><span>' + judul + '</span><span class="cek">●</span>');
    a.href = "#" + hal; a.dataset.hal = hal;
    wadah.appendChild(a);
  }

  var GONJONG_SVG = '<i><svg viewBox="0 0 30 26" aria-hidden="true">' +
    '<path d="M15 0 L30 26 L21.6 26 L15 11.2 L8.4 26 L0 26 Z" fill="currentColor"/></svg></i>';

  function buatBatas(cap, penutup) {
    var b = E("div", "batas" + (penutup ? " tutup" : ""));
    b.innerHTML =
      '<i class="titik-sisi ki"></i><i class="titik-sisi ka"></i>' +
      '<div class="rel"></div>' +
      '<div class="gonjong">' + new Array(6).join(GONJONG_SVG) + '</div>' +
      '<span class="cap">' + cap + '</span>';
    return b;
  }

  function halamanSederhana(bagian, nomor, wadahNav) {
    if (bagian.id === "kelas" && !PENGELOLA) return;
    if (bagian.id === "pantauan" && !ADMIN) return;
    var lembar = E("section", "lembar"); lembar.id = bagian.id;
    lembar.appendChild(E("h3", "bagian", '<span class="lambang">◆</span>' + bagian.judul));
    var hitung = { n: 0 };
    bagian.blok.forEach(function (b, i) {
      render(b, lembar, bagian.id, bagian.id + "." + i, bagian.judul, hitung);
    });
    isi.appendChild(lembar);
    tautan(wadahNav, bagian.id, nomor, bagian.judul);
  }

  AWAL.forEach(function (bagian, i) { halamanSederhana(bagian, "0" + (i + 1), navAwal); });

  UNIT.forEach(function (u) {
    var hal = "unit-" + u.no;
    var lembar = E("section", "lembar"); lembar.id = hal;

    lembar.appendChild(buatBatas("Unit " + u.no, false));

    var kepala = E("div", "unit-kepala");
    var isiKepala = E("div", "uk-teks");
    isiKepala.innerHTML = '<div class="tag">Unit ' + u.no + "</div><h2>" + u.judul +
      '</h2><p class="jenis">' + u.jenis + "</p>";
    var tujuan = E("div", "tujuan", "<b>Setelah mempelajari unit ini, pemelajar diharapkan mampu</b>");
    var ol = E("ol");
    u.tujuan.forEach(function (t) { ol.appendChild(E("li", null, t)); });
    tujuan.appendChild(ol); isiKepala.appendChild(tujuan);
    var kunciFotoUnit = "unit." + u.no;
    var kolomFoto = E("div", "uk-foto");
    var gbrUnit = document.createElement("img");
    gbrUnit.alt = "Gambaran Unit " + u.no + ": " + u.judul;
    gbrUnit.hidden = true;
    var kosongUnit = E("div", "uk-kosong",
      "<span>\uD83D\uDCF7</span><small>Gambaran Unit " + u.no + "<br>" +
      (ADMIN ? "Tekan tombol unggah untuk memasang gambar."
        : "Menunggu pengajar memasang gambar.") + "</small>");
    kolomFoto.appendChild(gbrUnit); kolomFoto.appendChild(kosongUnit);
    (function () {
      function pasangUnit(data) {
        if (data) { pasangGambarAman(gbrUnit, data); gbrUnit.hidden = false; kosongUnit.style.display = "none"; }
        else { gbrUnit.hidden = true; kosongUnit.style.display = ""; }
      }
      pasangUnit(FOTO_MODUL[kunciFotoUnit]);
      daftarkanPemasangFoto(kunciFotoUnit, pasangUnit);
      if (ADMIN) {
        var wadahTBU = E("div", "grup-tombol-foto");
        wadahTBU.style.position = "static";
        wadahTBU.style.marginTop = "6px";

        var tbUnitLink = E("button", "fd-unggah", "🔗 Tautan (Drive/URL)");
        tbUnitLink.type = "button";
        tbUnitLink.title = "Gunakan tautan Google Drive atau URL daring";
        tbUnitLink.addEventListener("click", function () {
          var skrg = FOTO_MODUL[kunciFotoUnit] || "";
          var baru = window.prompt("Masukkan tautan gambar unit (Google Drive atau URL):\nContoh: https://drive.google.com/file/d/xxx/view", skrg);
          if (baru === null) return;
          var tBaru = baru.trim();
          if (tBaru) {
            var urlGambar = ubahKeUrlGambar(tBaru);
            FOTO_MODUL[kunciFotoUnit] = urlGambar;
            simpanFotoModul(function (ok) {
              if (ok) window.alert("Gambar unit berhasil disimpan secara online ke Supabase!");
            });
            pasangUnit(urlGambar);
            if (tbResetU) tbResetU.style.display = "inline-block";
          }
        });
        wadahTBU.appendChild(tbUnitLink);

        var tbResetU = E("button", "fd-unggah", "↺ Reset");
        tbResetU.type = "button";
        tbResetU.style.display = FOTO_MODUL[kunciFotoUnit] ? "inline-block" : "none";
        tbResetU.addEventListener("click", function () {
          if (window.confirm("Hapus gambar unit ini?")) {
            delete FOTO_MODUL[kunciFotoUnit];
            simpanFotoModul();
            pasangUnit("");
            tbResetU.style.display = "none";
          }
        });
        wadahTBU.appendChild(tbResetU);

        kolomFoto.appendChild(wadahTBU);
      }
    })();
    kepala.appendChild(isiKepala);
    kepala.appendChild(kolomFoto);
    lembar.appendChild(kepala);

    var hitung = { n: 0 };
    u.bagian.forEach(function (bg, bi) {
      BAGIAN_KINI = bg.nama;
      var blokBagian = bg.blok.slice();
      if (/Prakegiatan/i.test(bg.nama) && FOTO_UNIT[u.no]) {
        var fd = FOTO_UNIT[u.no];
        blokBagian = [{ j: "fotodialog", tanya: fd.tanya, tutup: fd.tutup, foto: fd.foto }].concat(blokBagian);
      }
      if (/Wawasan/i.test(bg.nama) && RAGAM_WAWASAN[u.no] === "gambar") {
        var g = GAMBAR_WAWASAN[u.no] || {};
        blokBagian = blokBagian.filter(function (x) { return x.j !== "video"; });
        blokBagian = [{
          j: "fotoslot", kunci: "wawasan." + u.no,
          judul: g.judul || ("Wawasan Unit " + u.no),
          ikon: "\uD83C\uDFDE\uFE0F", ket: g.ket || ""
        }].concat(blokBagian);
      }
      if (/Berbicara/i.test(bg.nama) && LAFAL[u.no]) {
        blokBagian = blokBagian.concat([
          { j: "kegiatan", judul: "Latihan pelafalan", perintah: "Tekan tombol lalu ucapkan setiap kalimat dengan pelan dan jelas. Sistem akan menilai ketepatan pelafalan Anda." },
          { j: "lafal", kalimat: LAFAL[u.no] }
        ]);
      }
      lembar.appendChild(E("h3", "bagian", '<span class="lambang">' + (bg.ikon || "◆") + "</span>" + bg.nama));
      blokBagian.forEach(function (b, i) {
        render(b, lembar, hal, hal + "." + bi + "." + i, "Unit " + u.no + " · " + bg.nama, hitung);
      });
    });

    lembar.appendChild(buatBatas("Akhir Unit " + u.no, true));

    var gembok = E("div", "gembok-unit");
    gembok.dataset.unit = u.no;
    gembok.innerHTML = '<span class="ikon">\uD83D\uDD12</span>' +
      "<b>Unit " + u.no + " belum terbuka</b>" +
      "<span>Selesaikan Unit " + (u.no - 1) + " lebih dahulu. Setiap unit terbuka satu per satu " +
      "agar Anda dapat memusatkan perhatian pada satu topik sampai tuntas.</span>";
    var tbKeUnit = document.createElement("button");
    tbKeUnit.type = "button";
    tbKeUnit.textContent = "Buka Unit " + (u.no - 1);
    tbKeUnit.addEventListener("click", function () {
      var sasaran = document.getElementById("unit-" + (u.no - 1));
      if (sasaran) sasaran.scrollIntoView({ behavior: "smooth" });
    });
    gembok.appendChild(tbKeUnit);
    if (u.no > 1) lembar.insertBefore(gembok, lembar.firstChild.nextSibling);

    var kotakNilai = E("div", "nilai-unit");
    kotakNilai.dataset.hal = hal;
    kotakNilai.innerHTML =
      '<div class="nu-kop"><b>Nilai Unit ' + u.no + '</b>' +
      '<span class="nu-cap tunggu">Belum lengkap</span></div>' +
      '<div class="nu-baris"><span class="nu-angka">\u2013</span>' +
      '<span class="nu-satuan">dari 100</span></div>' +
      '<div class="nu-rinci"></div>' +
      '<p class="nu-ket"></p>';
    lembar.appendChild(kotakNilai);

    var lencana = E("div", "lencana");
    lencana.dataset.hal = hal;
    lencana.innerHTML = '<span class="ikon">🏅</span><div><b>Unit ' + u.no + " selesai</b>" +
      "<span>Selamat! Anda telah menuntaskan sebagian besar kegiatan pada unit ini.</span></div>";
    lembar.appendChild(lencana);

    isi.appendChild(lembar);
    tautan(navUnit, hal, "U" + u.no, u.judul);
  });

